+  *result = 0;
+  return NS_OK;
+}
+
+NS_IMETHODIMP nsMsgFileHdr::SetUidOnServer(uint32_t uid) {
+  // Message is not linked to an IMAP server, so we should never get here.
+  return NS_ERROR_NOT_IMPLEMENTED;
+}
